(2993, 650, '_wp_attachment_metadata', 'a:6:{s:5:\"width\";i:1554;s:6:\"height\";i:622;s:4:\"file\";s:34:\"2026/08/spp-5-6-kw-2.1-cut-min.jpg\";s:8:\"filesize\";i:55005;s:5:\"sizes\";a:5:{s:6:\"medium\";a:5:{s:4:\"file\";s:34:\"spp-5-6-kw-2.1-cut-min-300x120.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:120;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:6386;}s:5:\"large\";a:5:{s:4:\"file\";s:35:\"spp-5-6-kw-2.1-cut-min-1024x410.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:410;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:43960;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:34:\"spp-5-6-kw-2.1-cut-min-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:3981;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:34:\"spp-5-6-kw-2.1-cut-min-768x307.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:307;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:28559;}s:9:\"1536x1536\";a:5:{s:4:\"file\";s:35:\"spp-5-6-kw-2.1-cut-min-1536x615.jpg\";s:5:\"width\";i:1536;s:6:\"height\";i:615;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:79966;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),
