lass=\"screen-reader-response\"><p role=\"status\" aria-live=\"polite\"></p> <ul></ul></div>\r\n\r\n<fieldset class=\"hidden-fields-container\">\r\n</fieldset>\r\n<div class=\"form-style-6\">\r\n	<div class=\"columns_wrap\">\r\n		<div class=\"column-1_2\">\r\n			<p><span class=\"style-line\"><span class=\"wpcf7-form-control-wrap\" data-name=\"your-name\"></span></span>\r\n			</p>\r\n		</div>\r\n		<div class=\"column-1_2\">\r\n			<p><span class=\"style-line\"><span class=\"wpcf7-form-control-wrap\" data-name=\"your-phone\"></span></span>\r\n			</p>\r\n		</div>\r\n	</div>\r\n	<div class=\"columns_wrap margin-bottom\">\r\n		<div class=\"column-1_1\">\r\n			<p><span class=\"style-line\"><span class=\"wpcf7-form-control-wrap\" data-name=\"textarea-199\"><textarea cols=\"40\" rows=\"10\" class=\"wpcf7-form-control wpcf7-textarea\" name=\"textarea-199\"></textarea></span></span>\r\n			</p>\r\n		</div>\r\n	</div>\r\n	<div class=\"columns_wrap margin-bottom\">\r\n		<p><div id=\"cf7sr-6aa7f63f83ec2\" class=\"cf7sr-g-recaptcha\" data-theme=\"light\" data-type=\"image\" data-size=\"normal\" data-sitekey=\"6LeVGWYrAAAAAO3BJyr1kmS99nWbr3R9YNFbyTqz\"></div><span class=\"wpcf7-form-control-wrap cf7sr-recaptcha\" data-name=\"cf7sr-recaptcha\"></span>\r\n		</p>\r\n	</div>\r\n	<div style=\"display:none\">\r\n		<p><span class=\"wpcf7-form-control-wrap\" data-name=\"utm_source\"></span><br />\r\n<span class=\"wpcf7-form-control-wrap\" data-name=\"utm_medium\"></span><br />\r\n<span class=\"wpcf7-form-control-wrap\" data-name=\"utm_campaign\"></span><br />\r\n<span class=\"wpcf7-form-control-wrap\" data-name=\"utm_content\"></span><br />\r\n<span class=\"wpcf7-form-control-wrap\" data-name=\"utm_term\"></span>\r\n		</p>\r\n	</div>\r\n	<p>\r\n	</p>\r\n</div><div class=\"wpcf7-response-output\" aria-hidden=\"true\"></div>\r\n\r\n</div>\r\n		</div>\r\n				</div>\r\n					</div>\r\n		</div>\r\n							</div>\r\n		</section>\r\n							</div>\r\n		', 'Системи резервного живлення Deye', '', 'inherit', 'closed', 'closed', '', '884-revision-v1', '', '', '2026-09-14 16:27:29', '2026-09-14 13:27:29', '', 884, 'https://alteco.latul.space/?p=176242', 0, 'revision', '', 0);
